	const passed = H.summary("routing");
	server.stop();
	process.exit(passed ? 0 : 1);
}

main().catch(async (e) => {
	console.error("套件异常:", e);
	try { server?.stop(); } catch { /* ignore */ }
	process.exit(1);
});

